137	  public void setNeedsBootstrapMerge(boolean needsBootstrapMerge) {
138	    this.needsBootstrapMerge = needsBootstrapMerge;
139	  }
140	
141	  // Getter and Setter for useRecordPosition
142	  public boolean getShouldMergeUseRecordPosition() {
143	    return shouldMergeUseRecordPosition;
144	  }
145	
146	  public void setShouldMergeUseRecordPosition(boolean shouldMergeUseRecordPosition) {
147	    this.shouldMergeUseRecordPosition = shouldMergeUseRecordPosition;
148	  }
149	
