120	  protected ClosableIterator<IndexedRecord> getFileGroupIterator(int numFiles, boolean shouldReadPositions, boolean allowInflightCommits)
121	      throws IOException, InterruptedException {
122	    assert (numFiles >= 1 && numFiles <= keyRanges.size());
123	
124	    HoodieStorage hoodieStorage = new HoodieHadoopStorage(basePath, storageConf);
125	
126	    Option<FileSlice> fileSliceOpt =
127	        HoodieFileSliceTestUtils.getFileSlice(
128	            hoodieStorage,
129	            keyRanges.subList(0, numFiles),
