131	            operationTypes.subList(0, numFiles),
132	            instantTimes.subList(0, numFiles),
133	            shouldWritePositions.subList(0, numFiles),
134	            basePath,
135	            PARTITION_PATH,
136	            FILE_ID
137	        );
138	
139	    HoodieFileGroupReader<IndexedRecord> fileGroupReader =
140	        HoodieFileGroupReaderTestUtils.createFileGroupReader(
141	            fileSliceOpt,
142	            basePath,
143	            "1000", // Not used internally.
144	            AVRO_SCHEMA,
145	            shouldReadPositions,
146	            0L,
147	            Long.MAX_VALUE,
148	            properties,
149	            hoodieStorage,
150	            readerContext,
151	            metaClient,
152	            allowInflightCommits);
153	
154	    fileGroupReader.initRecordIterators();
155	    return fileGroupReader.getClosableIterator();
156	  }
157	}
